package com.mooncast.unified;
import android.app.*;import android.content.*;import android.os.*;import com.mooncast.locale.DeviceName;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** Generated names and identity sentinels in the isolated fixture package only. */
public final class DeviceNameDeviceTest {
 private final Instrumentation runner;private final Context context;
 public DeviceNameDeviceTest(Instrumentation runner){this.runner=runner;context=runner.getTargetContext();}
 public void run(){int code=Activity.RESULT_CANCELED;Bundle result=new Bundle();StringBuilder proof=new StringBuilder();Endpoint writer=null,reader=null;ArrayList<File> sentinels=new ArrayList<>();boolean preferencesSeeded=false;SharedPreferences uuid=context.getSharedPreferences("com.mooncast.tv.TvActivity",0),airplay=context.getSharedPreferences("airplay",0);
  try{require(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"disposable emulator only");
   for(String name:new String[]{"host-cert.pem","host-key.pem","paired-clients.json","airplay-identity.pem"}){File f=new File(context.getFilesDir(),name);require(!f.exists(),"no preexisting identity touched");Files.write(f.toPath(),("generated-only:"+name).getBytes(java.nio.charset.StandardCharsets.UTF_8));sentinels.add(f);}
   require(!uuid.contains("receiver_id")&&!airplay.contains("identity"),"no preexisting fixture UUID overwritten");preferencesSeeded=true;require(uuid.edit().putString("receiver_id","generated-uuid").commit()&&airplay.edit().putString("identity","001122334455").commit(),"identity prefs seed");
   writer=new Endpoint("DeviceNameFixtureService");reader=new Endpoint("DeviceNameReaderFixtureService");writer.bind();reader.bind();Bundle seeded=writer.query(1);require(seeded.getString("name").equals("Generated old name"),"production save old name");require(reader.query(6).getString("name").equals("Generated old name"),"second process first read");require(DeviceName.get(context).equals("Generated old name"),"instrumentation first read");
   writer.query(2);writer.await("armed");reader.query(4);reader.await("readStarted");SystemClock.sleep(500);require(!reader.query(0).getBoolean("readDone"),"concurrent read waits while AtomicFile write is active");require(writer.query(0).getBoolean("armed")&&!writer.query(0).getBoolean("writeDone"),"writer still paused at read barrier");writer.query(3);writer.await("writeDone");reader.await("readDone");
   require(writer.query(6).getString("name").equals("Generated 新名字")&&reader.query(6).getString("name").equals("Generated 新名字")&&DeviceName.get(context).equals("Generated 新名字"),"all live processes observe new name without rollback/cache restart");require(writer.query(0).getInt("pid")!=reader.query(0).getInt("pid")&&writer.query(0).getInt("pid")!=android.os.Process.myPid()&&reader.query(0).getInt("pid")!=android.os.Process.myPid(),"three distinct real processes");
   require(writer.query(7).getString("name").equals("Generated final name")&&reader.query(6).getString("name").equals("Generated final name")&&DeviceName.get(context).equals("Generated final name"),"exception releases storage lock and production save remains cross-process visible");require(uuid.getString("receiver_id","").equals("generated-uuid")&&airplay.getString("identity","").equals("001122334455"),"UUID and AirPlay identity preferences unchanged");
   for(File f:sentinels)require(new String(Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8).equals("generated-only:"+f.getName()),"generated identity sentinel unchanged "+f.getName());proof.append("Actual Android AtomicFile: paused writer blocks concurrent cross-process read, commit remains visible in three live processes; generated identity sentinel bytes unchanged.\n");code=Activity.RESULT_OK;
  }catch(Throwable failure){proof.append(android.util.Log.getStackTraceString(failure));}
  finally{if(preferencesSeeded)try{require(uuid.edit().remove("receiver_id").commit()&&airplay.edit().remove("identity").commit(),"identity prefs cleanup");}catch(Throwable failure){code=Activity.RESULT_CANCELED;proof.append("Preferences cleanup: ").append(failure).append('\n');}for(Endpoint endpoint:new Endpoint[]{writer,reader})if(endpoint!=null)try{endpoint.close();}catch(Throwable failure){code=Activity.RESULT_CANCELED;proof.append("Service cleanup: ").append(failure).append('\n');}for(File f:sentinels)try{Files.delete(f.toPath());}catch(Throwable failure){code=Activity.RESULT_CANCELED;proof.append("Sentinel cleanup: ").append(failure).append('\n');}}
  result.putString("stream",(code==Activity.RESULT_OK?"DEVICE_NAME_DEVICE_PASSED\n":"DEVICE_NAME_DEVICE_FAILED\n")+proof+"Scope: isolated generated fixture persistence and locking, not LAN discovery or real user pairing interoperability.\n");runner.finish(code,result);
 }
 private final class Endpoint implements ServiceConnection {
  private final Intent intent;private Messenger remote;private final CountDownLatch bound=new CountDownLatch(1);private int nonce;private final ConcurrentHashMap<Integer,CompletableFuture<Bundle>> pending=new ConcurrentHashMap<>();
  private final Messenger reply=new Messenger(new Handler(Looper.getMainLooper(),message->{CompletableFuture<Bundle> future=pending.remove(message.getData().getInt("nonce"));if(future!=null)future.complete(message.getData());return true;}));
  Endpoint(String name){intent=new Intent().setClassName(context.getPackageName(),"com.mooncast.locale."+name);}
  void bind()throws Exception{require(context.bindService(intent,this,Context.BIND_AUTO_CREATE)&&bound.await(15,TimeUnit.SECONDS),"name service bound");}
  public void onServiceConnected(ComponentName name,IBinder binder){remote=new Messenger(binder);bound.countDown();}public void onServiceDisconnected(ComponentName name){remote=null;}
  Bundle query(int what)throws Exception{require(remote!=null,"name endpoint alive");int token=++nonce;CompletableFuture<Bundle> future=new CompletableFuture<>();pending.put(token,future);Message message=Message.obtain();message.what=what;message.replyTo=reply;Bundle data=new Bundle();data.putInt("nonce",token);message.setData(data);remote.send(message);try{Bundle answer=future.get(7,TimeUnit.SECONDS);require(answer.getString("error","").isEmpty(),answer.getString("error"));return answer;}finally{pending.remove(token);}}
  void await(String key)throws Exception{long end=SystemClock.elapsedRealtime()+8000;while(SystemClock.elapsedRealtime()<end){if(query(0).getBoolean(key))return;SystemClock.sleep(50);}throw new AssertionError("name phase "+key);}
  void close()throws Exception{try{query(5);}finally{try{context.unbindService(this);}finally{context.stopService(intent);}}}
 }
 private static void require(boolean yes,String why){if(!yes)throw new AssertionError(why);}
}
